    fd, path = tempfile.mkstemp(suffix=".json")
    os.write(fd, b"[1, 2]\n")
    os.close(fd)
    parts = [
        grab(lambda: fromJSON("[1, 2, 3]", as_text=True)),
        grab(lambda: fromJSON("[true, false]", as_text=True)),
        grab(lambda: fromJSON('["a", "b"]', as_text=True)),
        grab(lambda: fromJSON('{"a": 1, "b": 2}', as_text=True)),
        grab(lambda: fromJSON('{"a": 1, "b": [true, null]}', as_text=True)),
        grab(lambda: fromJSON("[]", as_text=True)),
        grab(lambda: fromJSON("{}", as_text=True)),
        grab(lambda: fromJSON("[1, null]", as_text=True)),
        grab(lambda: fromJSON("[1, /*c*/ 2]", as_text=True, allow_comments=False)),
        grab(lambda: fromJSON("[[1,2],[3,4]]", as_text=True)),
        grab(lambda: fromJSON('[{"a":1},{"a":2}]', as_text=True)),
        grab(lambda: fromJSON('[1, "a"]', as_text=True)),
        grab(lambda: fromJSON("[1,]", as_text=True)),
        grab(lambda: fromJSON("[,1]", as_text=True)),
        grab(lambda: fromJSON("[1,,2]", as_text=True)),
        grab(lambda: fromJSON('{"a":1,"b":}', as_text=True)),
        grab(lambda: fromJSON("[1, 2]", as_text=True, simplify=False)),
        grab(lambda: fromJSON("[1, null]", as_text=True, null_value=NA)),
        grab(lambda: fromJSON('{"a":1,"b":2}', as_text=True, simplify_with_names=False)),
        grab(lambda: fromJSON("[1,2]", as_text=True, simplify=StrictCharacter)),
        grab(lambda: fromJSON(path)),
        grab(lambda: fromJSON("null", as_text=True)),
        grab(lambda: fromJSON('{"a":1,}', as_text=True)),
    ]
    return "\n".join(parts)


value = one()
elapsed = []
for _ in range(20):
    started = time.perf_counter()
    one()
    elapsed.append((time.perf_counter() - started) * 1000)
print(json.dumps({"value": value, "median_ms": statistics.median(elapsed)}, ensure_ascii=False))

